{
  "summary": "Engaged Singaporean couples who are first‑time applicants can apply for a BTO, provided they meet the standard eligibility criteria and have a valid HFE.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "First‑time couples (married or engaged) who are both Singapore Citizens and have never owned a flat or received a housing subsidy are eligible to apply for a BTO."
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "All first‑time applicants must hold a valid HDB Flat Eligibility (HFE) letter before submitting a BTO application."
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "Apply for an HFE letter via the HDB Flat Portal; the process typically takes up to 14 days."
    },
    {
      "claim_id": "c4",
      "kind": "preparation_step",
      "text": "Gather the required documents, such as NRICs, latest income documents (e.g., payslips or CPF statements), and the HFE letter."
    },
    {
      "claim_id": "c5",
      "kind": "preparation_step",
      "text": "Check that both applicants meet the minimum age requirement (21 years old) and are not barred from HDB purchases."
    },
    {
      "claim_id": "c6",
      "kind": "caveat",
      "text": "Exact income ceiling limits and grant eligibility can change; verify the latest figures on hdb.gov.sg before applying."
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}
